public class DateConverter {
    private LocalDate date;

    public String formatDate(DateFormat format) {
        DateTimeFormatter formatter;
        switch(format) {
            case MMDDYY:
                formatter = DateTimeFormatter.ofPattern("MMddyy");
                break;
            case YYMMDD:
                formatter = DateTimeFormatter.ofPattern("yyMMdd");
                break;
            case MMDDCCYY:
                formatter = DateTimeFormatter.ofPattern("MMddyyyy");
                break;
